#include <iostream>
#include <numeric>
#include <string>
#include <vector>
struct Draft {
    std::string title;
    std::vector<int> minutes;
};
bool valid(const Draft& draft) {
    if (draft.title.empty() || draft.minutes.empty() ||
        draft.minutes.size() > 3) return false;
    for (int duration : draft.minutes)
        if (duration < 1 || duration > 60) return false;
    return std::accumulate(draft.minutes.begin(),
                           draft.minutes.end(), 0) <= 90;
}
int main() {
    Draft draft{"Review", {20, 30}};
    // This caller remembers the validation boundary.
    if (valid(draft)) {
        std::cout << draft.title << ": "
                  << std::accumulate(draft.minutes.begin(),
                                     draft.minutes.end(), 0)
                  << " minutes\n";
    }
    draft.title.clear();
    std::cout << "after edit: valid=" << std::boolalpha
              << valid(draft) << '\n';
}

#include <iostream>
#include <numeric>
#include <stdexcept>
#include <vector>
void add_activity(std::vector<int>& minutes, int duration) {
    if (duration < 1 || duration > 60 || minutes.size() == 3)
        throw std::invalid_argument("activity");
    minutes.push_back(duration);
}
int main() {
    std::vector<int> minutes;
    add_activity(minutes, 60);
    add_activity(minutes, 60);
    const int total = std::accumulate(minutes.begin(), minutes.end(), 0);
    std::cout << "accepted steps=" << minutes.size() << '\n';
    std::cout << "draft total=" << total << '\n';
    // Passing step checks does not authorize publication.
    std::cout << "within final limit=" << std::boolalpha
              << (total <= 90) << '\n';
}
